import { useState, useEffect } from 'react';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { useToast } from '@/hooks/use-toast';
import { addInitiative, getDepartments } from '../lib/database';
import { parseCurrency } from '../lib/currency';

function AddInitiativeDialog({ open, onOpenChange, onSuccess }) {
  const { toast } = useToast();
  const [loading, setLoading] = useState(false);
  const [departments, setDepartments] = useState([]);
  const [formData, setFormData] = useState({
    name: '',
    department: '',
    status: 'لم تبدأ',
    completion_percentage: 0,
    planned_budget: '',
    used_budget: '',
    responsible_person: '',
    priority: 'متوسطة',
    description: ''
  });

  useEffect(() => {
    if (open) {
      loadDepartments();
      resetForm();
    }
  }, [open]);

  const loadDepartments = async () => {
    try {
      const depts = await getDepartments();
      setDepartments(depts);
    } catch (error) {
      console.error('Error loading departments:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في تحميل الإدارات",
        variant: "destructive",
      });
    }
  };

  const resetForm = () => {
    setFormData({
      name: '',
      department: '',
      status: 'لم تبدأ',
      completion_percentage: 0,
      planned_budget: '',
      used_budget: '',
      responsible_person: '',
      priority: 'متوسطة',
      description: ''
    });
  };

  const handleInputChange = (field, value) => {
    setFormData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!formData.name.trim()) {
      toast({
        title: "خطأ",
        description: "يرجى إدخال اسم المبادرة",
        variant: "destructive",
      });
      return;
    }

    if (!formData.department) {
      toast({
        title: "خطأ",
        description: "يرجى اختيار الإدارة",
        variant: "destructive",
      });
      return;
    }

    if (!formData.responsible_person.trim()) {
      toast({
        title: "خطأ",
        description: "يرجى إدخال اسم المسؤول",
        variant: "destructive",
      });
      return;
    }

    setLoading(true);
    
    try {
      const initiativeData = {
        ...formData,
        planned_budget: parseCurrency(formData.planned_budget) || 0,
        used_budget: parseCurrency(formData.used_budget) || 0,
        completion_percentage: parseInt(formData.completion_percentage) || 0,
        start_date: new Date(),
        end_date: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000) // Default to 1 year from now
      };

      await addInitiative(initiativeData);
      
      toast({
        title: "تم الحفظ",
        description: "تم إضافة المبادرة بنجاح",
      });
      
      onSuccess?.();
      onOpenChange(false);
      resetForm();
    } catch (error) {
      console.error('Error adding initiative:', error);
      toast({
        title: "خطأ",
        description: "حدث خطأ في إضافة المبادرة",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleCancel = () => {
    resetForm();
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[600px] max-h-[90vh] overflow-y-auto" dir="rtl">
        <DialogHeader>
          <DialogTitle className="text-right" style={{color: 'var(--brand-orange)'}}>
            إضافة مبادرة جديدة
          </DialogTitle>
          <DialogDescription className="text-right">
            أدخل تفاصيل المبادرة الجديدة من النموذج أدناه
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {/* Initiative Name */}
            <div className="md:col-span-2">
              <Label htmlFor="name" className="text-right block mb-2">
                اسم المبادرة *
              </Label>
              <Input
                id="name"
                placeholder="أدخل اسم المبادرة"
                value={formData.name}
                onChange={(e) => handleInputChange('name', e.target.value)}
                className="text-right"
                required
              />
            </div>

            {/* Department */}
            <div>
              <Label htmlFor="department" className="text-right block mb-2">
                الإدارة *
              </Label>
              <Select
                value={formData.department}
                onValueChange={(value) => handleInputChange('department', value)}
                required
              >
                <SelectTrigger className="text-right">
                  <SelectValue placeholder="اختر الإدارة" />
                </SelectTrigger>
                <SelectContent>
                  {departments.map((dept) => (
                    <SelectItem key={dept.id} value={dept.name}>
                      {dept.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Status */}
            <div>
              <Label htmlFor="status" className="text-right block mb-2">
                الحالة
              </Label>
              <Select
                value={formData.status}
                onValueChange={(value) => handleInputChange('status', value)}
              >
                <SelectTrigger className="text-right">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="لم تبدأ">لم تبدأ</SelectItem>
                  <SelectItem value="قيد التنفيذ">قيد التنفيذ</SelectItem>
                  <SelectItem value="مكتملة">مكتملة</SelectItem>
                  <SelectItem value="متأخرة">متأخرة</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {/* Priority */}
            <div>
              <Label htmlFor="priority" className="text-right block mb-2">
                الأولوية
              </Label>
              <Select
                value={formData.priority}
                onValueChange={(value) => handleInputChange('priority', value)}
              >
                <SelectTrigger className="text-right">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="عالية">عالية</SelectItem>
                  <SelectItem value="متوسطة">متوسطة</SelectItem>
                  <SelectItem value="منخفضة">منخفضة</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {/* Completion Percentage */}
            <div>
              <Label htmlFor="completion" className="text-right block mb-2">
                نسبة الإكمال (%)
              </Label>
              <Input
                id="completion"
                type="number"
                min="0"
                max="100"
                placeholder="0"
                value={formData.completion_percentage}
                onChange={(e) => handleInputChange('completion_percentage', e.target.value)}
                className="text-right"
              />
            </div>

            {/* Planned Budget */}
            <div>
              <Label htmlFor="planned_budget" className="text-right block mb-2">
                الميزانية المخططة (درهم)
              </Label>
              <Input
                id="planned_budget"
                type="number"
                step="0.01"
                placeholder="0.00"
                value={formData.planned_budget}
                onChange={(e) => handleInputChange('planned_budget', e.target.value)}
                className="text-right"
              />
            </div>

            {/* Used Budget */}
            <div>
              <Label htmlFor="used_budget" className="text-right block mb-2">
                الميزانية المستخدمة (درهم)
              </Label>
              <Input
                id="used_budget"
                type="number"
                step="0.01"
                placeholder="0.00"
                value={formData.used_budget}
                onChange={(e) => handleInputChange('used_budget', e.target.value)}
                className="text-right"
              />
            </div>

            {/* Responsible Person */}
            <div className="md:col-span-2">
              <Label htmlFor="responsible_person" className="text-right block mb-2">
                المسؤول *
              </Label>
              <Input
                id="responsible_person"
                placeholder="أدخل اسم المسؤول عن المبادرة"
                value={formData.responsible_person}
                onChange={(e) => handleInputChange('responsible_person', e.target.value)}
                className="text-right"
                required
              />
            </div>

            {/* Description */}
            <div className="md:col-span-2">
              <Label htmlFor="description" className="text-right block mb-2">
                الوصف
              </Label>
              <Textarea
                id="description"
                placeholder="أدخل وصف تفصيلي للمبادرة (اختياري)"
                value={formData.description}
                onChange={(e) => handleInputChange('description', e.target.value)}
                className="text-right min-h-[80px]"
                rows={3}
              />
            </div>
          </div>

          <DialogFooter className="flex justify-start gap-2 pt-4">
            <Button
              type="button"
              variant="outline"
              onClick={handleCancel}
              disabled={loading}
            >
              إلغاء
            </Button>
            <Button
              type="submit"
              disabled={loading}
              className="text-white"
              style={{backgroundColor: 'var(--brand-orange)'}}
            >
              {loading ? 'جاري الحفظ...' : 'حفظ المبادرة'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

export default AddInitiativeDialog;
